function casoMaestro(a, b, d) {
  const combinar = b ** d;
  if (a < combinar) {
    return "domina combinar";
  }
  if (a === combinar) {
    return "equilibrado";
  }
  return "dominan las hojas";
}

function buscarParada(estaciones, objetivo) {
  let comparaciones = 0;
  for (let i = 0; i < estaciones.length; i++) {
    comparaciones++;
    if (estaciones[i] === objetivo) return [i, comparaciones];
  }
  return [-1, comparaciones];
}

function medirConsultas(estaciones, consultas) {
  const costes = [];
  let total = 0;
  for (const objetivo of consultas) {
    const resultado = buscarParada(estaciones, objetivo);
    costes.push(resultado[1]);
    total += resultado[1];
  }
  return [costes, total, costes.length === 0 ? null : total / costes.length];
}

function perfilarConsultas(estaciones, consultas) {
  const medicion = medirConsultas(estaciones, consultas);
  return {
    costes: medicion[0],
    total: medicion[1],
    media: medicion[2],
    mejorPosible: estaciones.length === 0 ? 0 : 1,
    peorPosible: estaciones.length
  };
}

function resumirAltas(cantidad, duplicar) {
  let capacidad = 1;
  let copias = 0;
  let pico = 1;
  for (let ocupadas = 0; ocupadas < cantidad; ocupadas++) {
    if (ocupadas === capacidad) {
      const anterior = capacidad;
      capacidad = duplicar ? anterior * 2 : anterior + 1;
      copias += ocupadas;
      pico = anterior + capacidad;
    }
  }
  return [capacidad, copias, cantidad + copias, pico];
}

function compararAltas(cantidad) {
  return [resumirAltas(cantidad, true), resumirAltas(cantidad, false)];
}

function auditarCatalogo(estaciones, consultas, altas) {
  return { busqueda: perfilarConsultas(estaciones, consultas), crecimiento: compararAltas(altas) };
}

function sumarMinutos(tramos) {
  let total = 0;
  for (const minutos of tramos) total += minutos;
  return total;
}

function medirPila(tramos) {
  let pico = 0;
  function desde(indice, activas) {
    if (activas > pico) pico = activas;
    if (indice === tramos.length) return 0;
    return tramos[indice] + desde(indice + 1, activas + 1);
  }
  const total = desde(0, 1);
  return [total, pico];
}

function auditarEspacio(tramos, altas) {
  return {
    total: sumarMinutos(tramos),
    llamadasActivas: medirPila(tramos)[1],
    picoCeldasReservadas: resumirAltas(altas, true)[3]
  };
}

function sumarPrefijo(tramos, fin) {
  let total = 0;
  for (let i = 0; i < fin; i++) total += tramos[i];
  return total;
}

function sumarIntervalo(tramos, inicio, fin) {
  let total = 0;
  for (let i = inicio; i < fin; i++) total += tramos[i];
  return total;
}

function intervaloValido(tramos, inicio, fin) {
  return Number.isInteger(inicio) && Number.isInteger(fin)
    && 0 <= inicio && inicio <= fin && fin <= tramos.length;
}

function distanciaTramo(tramos, inicio, fin) {
  if (!intervaloValido(tramos, inicio, fin)) return null;
  return sumarIntervalo(tramos, inicio, fin);
}

function informeDirecto(tramos, consultas) {
  const resultados = [];
  let operaciones = 0;
  for (const consulta of consultas) {
    const inicio = consulta[0];
    const fin = consulta[1];
    const total = distanciaTramo(tramos, inicio, fin);
    resultados.push(total);
    if (total !== null) operaciones += fin - inicio;
  }
  return { resultados, operaciones };
}

function informeConPrefijos(tramos, consultas) {
  const prefijos = [0];
  for (const minutos of tramos) {
    prefijos.push(prefijos[prefijos.length - 1] + minutos);
  }
  const resultados = [];
  let operaciones = tramos.length;
  for (const consulta of consultas) {
    const inicio = consulta[0];
    const fin = consulta[1];
    if (intervaloValido(tramos, inicio, fin)) {
      resultados.push(prefijos[fin] - prefijos[inicio]);
      operaciones++;
    } else {
      resultados.push(null);
    }
  }
  return { resultados, operaciones, celdasExtra: prefijos.length };
}

function decidirEstrategia(tramos, consultas, presupuesto) {
  const directo = informeDirecto(tramos, consultas);
  const indice = informeConPrefijos(tramos, consultas);
  let coinciden = directo.resultados.length === indice.resultados.length;
  for (let i = 0; i < directo.resultados.length; i++) {
    if (directo.resultados[i] !== indice.resultados[i]) coinciden = false;
  }
  const usarIndice = coinciden && indice.celdasExtra <= presupuesto
    && indice.operaciones < directo.operaciones;
  return {
    resultados: directo.resultados,
    coinciden,
    operacionesDirectas: directo.operaciones,
    operacionesIndice: indice.operaciones,
    celdasIndice: indice.celdasExtra,
    estrategia: usarIndice ? "prefijos" : "directa"
  };
}

function copiarBuffer(origen, longitud, capacidad) {
  const celdas = Array(capacidad).fill(null);
  for (let i = 0; i < longitud; i++) celdas[i] = origen[i];
  return celdas;
}

function altasBuffer(nombres) {
  let celdas = [null];
  let longitud = 0;
  let copias = 0;
  for (const nombre of nombres) {
    if (longitud === celdas.length) {
      celdas = copiarBuffer(celdas, longitud, celdas.length * 2);
      copias += longitud;
    }
    celdas[longitud] = nombre;
    longitud++;
  }
  return { celdas, longitud, copias };
}

function catalogoBuffer(nombres, consultas) {
  const { celdas, longitud, copias } = altasBuffer(nombres);
  const encontrados = consultas.map((i) =>
    i >= 0 && i < longitud ? celdas[i] : null,
  );
  return { capacidad: celdas.length, longitud, copias, encontrados };
}

function enlazarSimple(datos) {
  let cabeza = null;
  for (let i = datos.length - 1; i >= 0; i--) {
    cabeza = { valor: datos[i], siguiente: cabeza };
  }
  return cabeza;
}

function leerSimple(cabeza) {
  const datos = [];
  for (let actual = cabeza; actual !== null; actual = actual.siguiente)
    datos.push(actual.valor);
  return datos;
}
function retirarSimple(cabeza, nombre) {
  if (cabeza?.valor === nombre) return cabeza.siguiente;
  for (
    let anterior = cabeza;
    anterior?.siguiente;
    anterior = anterior.siguiente
  ) {
    if (anterior.siguiente.valor === nombre) {
      anterior.siguiente = anterior.siguiente.siguiente;
      break;
    }
  }
  return cabeza;
}
function quitarSimple(cabeza, nombre) {
  return retirarSimple(enlazarSimple(leerSimple(cabeza)), nombre);
}

function recorridoSimple(datos, cambios) {
  let cabeza = enlazarSimple(datos);
  for (const [accion, nombre] of cambios) {
    if (accion === "frente") cabeza = { valor: nombre, siguiente: cabeza };
    else cabeza = retirarSimple(cabeza, nombre);
  }
  return leerSimple(cabeza);
}

function crearDoble() {
  const raiz = {};
  raiz.siguiente = raiz;
  raiz.anterior = raiz;
  return raiz;
}
function ponerAntes(destino, valor) {
  const nodo = { valor, anterior: destino.anterior, siguiente: destino };
  nodo.anterior.siguiente = nodo;
  destino.anterior = nodo;
  return nodo;
}
function sacarDoble(nodo) {
  nodo.anterior.siguiente = nodo.siguiente;
  nodo.siguiente.anterior = nodo.anterior;
}
function leerDoble(raiz, enlace) {
  const salida = [];
  for (let nodo = raiz[enlace]; nodo !== raiz; nodo = nodo[enlace])
    salida.push(nodo.valor);
  return salida;
}
function vistaDoble(datos) {
  const raiz = crearDoble();
  for (const dato of datos) ponerAntes(raiz, dato);
  return {
    ida: leerDoble(raiz, "siguiente"),
    vuelta: leerDoble(raiz, "anterior"),
  };
}

function bajaDoble(datos, indice) {
  const raiz = crearDoble();
  for (const dato of datos) ponerAntes(raiz, dato);
  let i = 0;
  let retirado = null;
  for (let nodo = raiz.siguiente; nodo !== raiz; nodo = nodo.siguiente) {
    if (i++ === indice) {
      retirado = nodo.valor;
      sacarDoble(nodo);
      break;
    }
  }
  return {
    retirado,
    ida: leerDoble(raiz, "siguiente"),
    vuelta: leerDoble(raiz, "anterior"),
  };
}

function avisoDoble(datos, indice) {
  return { antes: vistaDoble(datos), despues: bajaDoble(datos, indice) };
}

function historialPila(acciones) {
  const pila = [];
  const respuestas = [];
  for (const [accion, etiqueta] of acciones) {
    if (accion === "guardar") pila.push(etiqueta);
    else if (accion === "ver") respuestas.push(pila[pila.length - 1] ?? null);
    else respuestas.push(pila.pop() ?? null);
  }
  return respuestas;
}

function revisarCierres(texto) {
  const pares = { ")": "(", "]": "[", "}": "{" };
  const pila = [];
  for (let i = 0; i < texto.length; i++) {
    const actual = texto[i];
    if ("([{".includes(actual)) pila.push(actual);
    else if (")]}".includes(actual) && pila.pop() !== pares[actual]) {
      return { valido: false, error: i };
    }
  }
  return pila.length
    ? { valido: false, error: texto.length }
    : { valido: true, error: null };
}

function panelReglas(acciones, reglas) {
  return {
    historial: historialPila(acciones),
    revisiones: reglas.map(revisarCierres),
  };
}

function indiceCircular(inicio, paso, capacidad) {
  return (inicio + paso) % capacidad;
}

function estadoCola(capacidad, acciones) {
  const celdas = Array(capacidad);
  let cabeza = 0;
  let cantidad = 0;
  const respuestas = [];
  for (const [accion, aviso] of acciones) {
    if (accion === "entrar") {
      const hayEspacio = cantidad < capacidad;
      if (hayEspacio) {
        celdas[indiceCircular(cabeza, cantidad, capacidad)] = aviso;
        cantidad++;
      }
      respuestas.push(hayEspacio);
    } else if (cantidad === 0) respuestas.push(null);
    else {
      respuestas.push(celdas[cabeza]);
      celdas[cabeza] = undefined;
      cabeza = indiceCircular(cabeza, 1, capacidad);
      cantidad--;
    }
  }
  const pendientes = [];
  for (let i = 0; i < cantidad; i++)
    pendientes.push(celdas[indiceCircular(cabeza, i, capacidad)]);
  return { respuestas, pendientes };
}

function turnosCentral(capacidad, acciones) {
  const { respuestas, pendientes } = estadoCola(capacidad, acciones);
  return {
    respuestas,
    pendientes,
    siguiente: pendientes[0] ?? null,
    libres: capacidad - pendientes.length,
  };
}

function crearDeque(capacidad) {
  const celdas = Array(capacidad);
  let inicio = 0;
  let cantidad = 0;
  const indice = (paso) => (inicio + paso + capacidad) % capacidad;
  return {
    cantidad: () => cantidad,
    frente: () => (cantidad ? celdas[inicio] : null),
    fondo: () => (cantidad ? celdas[indice(cantidad - 1)] : null),
    entrarFrente(valor) {
      if (cantidad === capacidad) return false;
      inicio = indice(-1);
      celdas[inicio] = valor;
      cantidad++;
      return true;
    },
    entrarFondo(valor) {
      if (cantidad === capacidad) return false;
      celdas[indice(cantidad++)] = valor;
      return true;
    },
    salirFrente() {
      if (!cantidad) return null;
      const valor = celdas[inicio];
      celdas[inicio] = undefined;
      inicio = indice(1);
      cantidad--;
      return valor;
    },
    salirFondo() {
      if (!cantidad) return null;
      const posicion = indice(--cantidad);
      const valor = celdas[posicion];
      celdas[posicion] = undefined;
      return valor;
    },
  };
}
function manejarDeque(capacidad, acciones) {
  const d = crearDeque(capacidad);
  return acciones.map(([operacion, valor]) => d[operacion](valor));
}

function maximosVentana(datos, k) {
  if (k < 1 || k > datos.length) return [];
  const candidatos = crearDeque(k);
  const maximos = [];
  for (let i = 0; i < datos.length; i++) {
    if (candidatos.cantidad() && candidatos.frente() <= i - k)
      candidatos.salirFrente();
    while (candidatos.cantidad() && datos[candidatos.fondo()] <= datos[i])
      candidatos.salirFondo();
    candidatos.entrarFondo(i);
    if (i >= k - 1) maximos.push(datos[candidatos.frente()]);
  }
  return maximos;
}

function picosOcupacion(datos, k) {
  return maximosVentana(datos, k).map((maximo, inicio) => ({ inicio, maximo }));
}

function indiceHash(clave, capacidad) {
  let hash = 0;
  for (let i = 0; i < clave.length; i++) {
    hash = (31 * hash + clave.charCodeAt(i)) % capacidad;
  }
  return hash;
}

function indiceEncadenado(capacidad, registros) {
  const buckets = Array.from({ length: capacidad }, () => []);
  for (const [clave, valor] of registros) {
    const bucket = buckets[indiceHash(clave, capacidad)];
    const existente = bucket.find((par) => par[0] === clave);
    if (existente) existente[1] = valor;
    else bucket.push([clave, valor]);
  }
  return buckets;
}

function consultasEncadenadas(capacidad, registros, claves) {
  const buckets = indiceEncadenado(capacidad, registros);
  const respuestas = claves.map((clave) => {
    const bucket = buckets[indiceHash(clave, capacidad)];
    return bucket.find((par) => par[0] === clave)?.[1] ?? null;
  });
  return { respuestas, ocupacion: buckets.map((bucket) => bucket.length) };
}

function sondear(tabla, clave) {
  const inicio = indiceHash(clave, tabla.length);
  let hueco = -1;
  for (let paso = 0; paso < tabla.length; paso++) {
    const i = (inicio + paso) % tabla.length;
    const celda = tabla[i];
    if (celda === null) return { existe: false, indice: hueco < 0 ? i : hueco };
    if (celda === false) {
      if (hueco < 0) hueco = i;
    } else if (celda[0] === clave) return { existe: true, indice: i };
  }
  return { existe: false, indice: hueco };
}

function ejecutarSondeo(acciones) {
  let tabla = Array(4).fill(null);
  let activos = 0;
  let usados = 0;
  const respuestas = [];
  for (const [accion, clave, valor] of acciones) {
    let { existe, indice } = sondear(tabla, clave);
    if (accion === "leer") respuestas.push(existe ? tabla[indice][1] : null);
    else if (accion === "borrar") {
      if (existe) {
        tabla[indice] = false;
        activos--;
      }
      respuestas.push(existe);
    } else if (existe) tabla[indice][1] = valor;
    else {
      if (tabla[indice] === null && (usados + 1) * 2 > tabla.length) {
        const capacidad =
          (activos + 1) * 2 > tabla.length ? tabla.length * 2 : tabla.length;
        const anterior = tabla;
        tabla = Array(capacidad).fill(null);
        for (const par of anterior) {
          if (par) tabla[sondear(tabla, par[0]).indice] = par;
        }
        usados = activos;
        indice = sondear(tabla, clave).indice;
      }
      if (tabla[indice] === null) usados++;
      tabla[indice] = [clave, valor];
      activos++;
    }
  }
  return { respuestas, capacidad: tabla.length, activos, usados };
}

function indiceEstacionesAbierto(acciones) {
  const estado = ejecutarSondeo(acciones);
  return { ...estado, marcas: estado.usados - estado.activos };
}

function igualdadNativa() {
  const objeto = { id: 1 };
  const copia = { id: 1 };
  const mapa = new Map([
    [NaN, "primero"],
    [NaN, "segundo"],
    [-0, "cero"],
    ["u", undefined],
  ]);
  return {
    nanRepite: mapa.get(NaN) === "segundo",
    cerosCoinciden: mapa.has(+0),
    tipos: new Set([1, "1"]).size,
    objetos: new Set([objeto, objeto, copia]).size,
    reconoceReferencia: new Set([objeto]).has(objeto),
    reconoceCopia: new Set([objeto]).has(copia),
    indefinidoPresente: mapa.has("u") && mapa.get("u") === undefined,
  };
}

function ordenNativo(acciones) {
  const registros = new Map();
  const activas = new Set();
  for (const [accion, clave, valor] of acciones) {
    if (accion === "guardar") {
      registros.set(clave, valor);
      activas.add(clave);
    } else {
      registros.delete(clave);
      activas.delete(clave);
    }
  }
  return { registros: Array.from(registros), activas: Array.from(activas) };
}

function consultasNativas(acciones, claves) {
  const { registros, activas } = ordenNativo(acciones);
  const porClave = new Map(registros);
  return {
    activas,
    respuestas: claves.map((clave) => porClave.get(clave) ?? null),
  };
}

function crearLRU(capacidad) {
  const raiz = crearDoble();
  const indice = new Map();
  function promover(nodo) {
    sacarDoble(nodo);
    indice.set(nodo.valor.clave, ponerAntes(raiz, nodo.valor));
  }
  return {
    leer(clave) {
      const nodo = indice.get(clave);
      if (!nodo) return { acierto: false, valor: null };
      promover(nodo);
      return { acierto: true, valor: nodo.valor.valor };
    },
    guardar(clave, valor) {
      if (capacidad === 0) return;
      const nodo = indice.get(clave);
      if (nodo) {
        nodo.valor.valor = valor;
        promover(nodo);
        return;
      }
      if (indice.size === capacidad) {
        const expulsado = raiz.siguiente;
        sacarDoble(expulsado);
        indice.delete(expulsado.valor.clave);
      }
      indice.set(clave, ponerAntes(raiz, { clave, valor }));
    },
    orden() {
      const claves = [];
      for (let nodo = raiz.siguiente; nodo !== raiz; nodo = nodo.siguiente)
        claves.push(nodo.valor.clave);
      return claves;
    },
  };
}
function estadoCache(capacidad, acciones) {
  const cache = crearLRU(capacidad);
  const resultados = [];
  for (const [accion, clave, valor] of acciones) {
    if (accion === "guardar") cache.guardar(clave, valor);
    else resultados.push(cache.leer(clave));
  }
  return { resultados, orden: cache.orden() };
}

function diagnosticoLRU(capacidad, acciones) {
  const { resultados, orden } = estadoCache(capacidad, acciones);
  let aciertos = 0;
  for (const resultado of resultados) if (resultado.acierto) aciertos++;
  return { aciertos, fallos: resultados.length - aciertos, orden };
}

function tableroCache(capacidad, acciones) {
  const estado = diagnosticoLRU(capacidad, acciones);
  return {
    ...estado,
    primeraExpulsion:
      estado.orden.length === capacidad ? (estado.orden[0] ?? null) : null,
  };
}

