function casoMaestro(a, b, d) {
  const combinar = b ** d;
  if (a < combinar) {
    return "domina combinar";
  }
  if (a === combinar) {
    return "equilibrado";
  }
  return "dominan las hojas";
}

function buscarParada(estaciones, objetivo) {
  let comparaciones = 0;
  for (let i = 0; i < estaciones.length; i++) {
    comparaciones++;
    if (estaciones[i] === objetivo) return [i, comparaciones];
  }
  return [-1, comparaciones];
}

function medirConsultas(estaciones, consultas) {
  const costes = [];
  let total = 0;
  for (const objetivo of consultas) {
    const resultado = buscarParada(estaciones, objetivo);
    costes.push(resultado[1]);
    total += resultado[1];
  }
  return [costes, total, costes.length === 0 ? null : total / costes.length];
}

function perfilarConsultas(estaciones, consultas) {
  const medicion = medirConsultas(estaciones, consultas);
  return {
    costes: medicion[0],
    total: medicion[1],
    media: medicion[2],
    mejorPosible: estaciones.length === 0 ? 0 : 1,
    peorPosible: estaciones.length
  };
}

function resumirAltas(cantidad, duplicar) {
  let capacidad = 1;
  let copias = 0;
  let pico = 1;
  for (let ocupadas = 0; ocupadas < cantidad; ocupadas++) {
    if (ocupadas === capacidad) {
      const anterior = capacidad;
      capacidad = duplicar ? anterior * 2 : anterior + 1;
      copias += ocupadas;
      pico = anterior + capacidad;
    }
  }
  return [capacidad, copias, cantidad + copias, pico];
}

function compararAltas(cantidad) {
  return [resumirAltas(cantidad, true), resumirAltas(cantidad, false)];
}

function auditarCatalogo(estaciones, consultas, altas) {
  return { busqueda: perfilarConsultas(estaciones, consultas), crecimiento: compararAltas(altas) };
}

function sumarMinutos(tramos) {
  let total = 0;
  for (const minutos of tramos) total += minutos;
  return total;
}

function medirPila(tramos) {
  let pico = 0;
  function desde(indice, activas) {
    if (activas > pico) pico = activas;
    if (indice === tramos.length) return 0;
    return tramos[indice] + desde(indice + 1, activas + 1);
  }
  const total = desde(0, 1);
  return [total, pico];
}

function auditarEspacio(tramos, altas) {
  return {
    total: sumarMinutos(tramos),
    llamadasActivas: medirPila(tramos)[1],
    picoCeldasReservadas: resumirAltas(altas, true)[3]
  };
}

function sumarPrefijo(tramos, fin) {
  let total = 0;
  for (let i = 0; i < fin; i++) total += tramos[i];
  return total;
}

function sumarIntervalo(tramos, inicio, fin) {
  let total = 0;
  for (let i = inicio; i < fin; i++) total += tramos[i];
  return total;
}

function intervaloValido(tramos, inicio, fin) {
  return Number.isInteger(inicio) && Number.isInteger(fin)
    && 0 <= inicio && inicio <= fin && fin <= tramos.length;
}

function distanciaTramo(tramos, inicio, fin) {
  if (!intervaloValido(tramos, inicio, fin)) return null;
  return sumarIntervalo(tramos, inicio, fin);
}

function informeDirecto(tramos, consultas) {
  const resultados = [];
  let operaciones = 0;
  for (const consulta of consultas) {
    const inicio = consulta[0];
    const fin = consulta[1];
    const total = distanciaTramo(tramos, inicio, fin);
    resultados.push(total);
    if (total !== null) operaciones += fin - inicio;
  }
  return { resultados, operaciones };
}

function informeConPrefijos(tramos, consultas) {
  const prefijos = [0];
  for (const minutos of tramos) {
    prefijos.push(prefijos[prefijos.length - 1] + minutos);
  }
  const resultados = [];
  let operaciones = tramos.length;
  for (const consulta of consultas) {
    const inicio = consulta[0];
    const fin = consulta[1];
    if (intervaloValido(tramos, inicio, fin)) {
      resultados.push(prefijos[fin] - prefijos[inicio]);
      operaciones++;
    } else {
      resultados.push(null);
    }
  }
  return { resultados, operaciones, celdasExtra: prefijos.length };
}

function decidirEstrategia(tramos, consultas, presupuesto) {
  const directo = informeDirecto(tramos, consultas);
  const indice = informeConPrefijos(tramos, consultas);
  let coinciden = directo.resultados.length === indice.resultados.length;
  for (let i = 0; i < directo.resultados.length; i++) {
    if (directo.resultados[i] !== indice.resultados[i]) coinciden = false;
  }
  const usarIndice = coinciden && indice.celdasExtra <= presupuesto
    && indice.operaciones < directo.operaciones;
  return {
    resultados: directo.resultados,
    coinciden,
    operacionesDirectas: directo.operaciones,
    operacionesIndice: indice.operaciones,
    celdasIndice: indice.celdasExtra,
    estrategia: usarIndice ? "prefijos" : "directa"
  };
}

function copiarBuffer(origen, longitud, capacidad) {
  const celdas = Array(capacidad).fill(null);
  for (let i = 0; i < longitud; i++) celdas[i] = origen[i];
  return celdas;
}

function altasBuffer(nombres) {
  let celdas = [null];
  let longitud = 0;
  let copias = 0;
  for (const nombre of nombres) {
    if (longitud === celdas.length) {
      celdas = copiarBuffer(celdas, longitud, celdas.length * 2);
      copias += longitud;
    }
    celdas[longitud] = nombre;
    longitud++;
  }
  return { celdas, longitud, copias };
}

function catalogoBuffer(nombres, consultas) {
  const { celdas, longitud, copias } = altasBuffer(nombres);
  const encontrados = consultas.map((i) =>
    i >= 0 && i < longitud ? celdas[i] : null,
  );
  return { capacidad: celdas.length, longitud, copias, encontrados };
}

function enlazarSimple(datos) {
  let cabeza = null;
  for (let i = datos.length - 1; i >= 0; i--) {
    cabeza = { valor: datos[i], siguiente: cabeza };
  }
  return cabeza;
}

function leerSimple(cabeza) {
  const datos = [];
  for (let actual = cabeza; actual !== null; actual = actual.siguiente)
    datos.push(actual.valor);
  return datos;
}
function retirarSimple(cabeza, nombre) {
  if (cabeza?.valor === nombre) return cabeza.siguiente;
  for (
    let anterior = cabeza;
    anterior?.siguiente;
    anterior = anterior.siguiente
  ) {
    if (anterior.siguiente.valor === nombre) {
      anterior.siguiente = anterior.siguiente.siguiente;
      break;
    }
  }
  return cabeza;
}
function quitarSimple(cabeza, nombre) {
  return retirarSimple(enlazarSimple(leerSimple(cabeza)), nombre);
}

function recorridoSimple(datos, cambios) {
  let cabeza = enlazarSimple(datos);
  for (const [accion, nombre] of cambios) {
    if (accion === "frente") cabeza = { valor: nombre, siguiente: cabeza };
    else cabeza = retirarSimple(cabeza, nombre);
  }
  return leerSimple(cabeza);
}

function crearDoble() {
  const raiz = {};
  raiz.siguiente = raiz;
  raiz.anterior = raiz;
  return raiz;
}
function ponerAntes(destino, valor) {
  const nodo = { valor, anterior: destino.anterior, siguiente: destino };
  nodo.anterior.siguiente = nodo;
  destino.anterior = nodo;
  return nodo;
}
function sacarDoble(nodo) {
